const IMG="";
const IMG2="";
const IMG3="";
const IMG4="";
const IMG5="";
const IMG6="";
const IMG7="";
const IMG8="";
const IMG9="";
const IMG10="";
const IMG11="";
const IMG12="";
const IMG13="";
const IMG14="";
const IMG15="";
const IMG16="";
const IMG17="data:image/jpeg;base64,";
const IMG18="data:image/jpeg;base64,";
const IMG19="";
const IMG20="";
const IMG21="";
const IMG22="";
const IMG23="";
const IMG24="";
const IMG25="";
const IMG26="data:image/jpeg;base64,";
const IMG27="data:image/jpeg;base64,";
const IMG28="";
const IMG29="data:image/jpeg;base64,";
const IMG30="";
const IMG31="data:image/jpeg;base64,";
const P=[{id:41,n:"سوار فضي بقلوب لامعة",c:"أساور",p:319,t:"img",src:"IMG31"},
{id:39,n:"سوار فضي بحجر دائري لامع",c:"أساور",p:149,t:"img",src:"IMG29"},
{id:37,n:"سوار فضي قابل للتعديل بحجر لامع",c:"أساور",p:139,t:"img",src:"IMG27"},
{id:36,n:"سوار فضي بكريستالات زرقاء وشفافة",c:"أساور",p:329,t:"img",src:"IMG26"},
{id:28,n:"سوار فضي بفراشات",c:"أساور",p:169,t:"img",src:"IMG18"},
{id:27,n:"سوار فضي بأحجار زرقاء",c:"أساور",p:229,t:"img",src:"IMG17"}];
const cats=["أساور"];let cat="أساور",cart={};
const el=i=>document.getElementById(i);
function watch(x){
const k=x.shape=="s",strap=x.mesh?`<rect x="45" y="0" width="30" height="140" rx="4" fill="${x.s}" opacity=".7"/>`+Array.from({length:14},(_,i)=>`<line x1="45" x2="75" y1="${i*10+5}" y2="${i*10+5}" stroke="#fff" opacity=".5"/>`).join(""):`<rect x="46" y="0" width="28" height="140" rx="9" fill="${x.s}" opacity=".85"/>`;
const stitch=x.s=="#d8c1a3"?`<line x1="60" x2="60" y1="4" y2="30" stroke="#fff" stroke-dasharray="3 3"/><line x1="60" x2="60" y1="110" y2="136" stroke="#fff" stroke-dasharray="3 3"/>`:"";
const case_=k?`<rect x="28" y="38" width="64" height="64" rx="12" fill="${x.a}"/><rect x="34" y="44" width="52" height="52" rx="8" fill="${x.f}"/>`:`<circle cx="60" cy="70" r="36" fill="${x.a}"/><circle cx="60" cy="70" r="30" fill="${x.f}"/>`;
const gems=x.gem?Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<circle cx="${60+33*Math.cos(a)}" cy="${70+33*Math.sin(a)}" r="2.2" fill="#fff"/>`}).join(""):"";
const ticks=[0,3,6,9].map(i=>{const a=i*Math.PI/6;return `<circle cx="${60+22*Math.sin(a)}" cy="${70-22*Math.cos(a)}" r="1.8" fill="${x.a}"/>`}).join("");
return `<svg width="130" height="150" viewBox="0 0 120 140">${strap}${stitch}${case_}${gems}${ticks}<path d="M60 70V52M60 70l12 8" stroke="#2a2224" stroke-width="2.6" stroke-linecap="round"/><circle cx="60" cy="70" r="2.8" fill="#2a2224"/></svg>`}
function brace(x){
const pts=(n,r,f)=>Array.from({length:n},(_,i)=>{const a=i*2*Math.PI/n;return f(60+r*Math.cos(a),60+r*Math.sin(a),a)}).join("");
let b="";
if(x.t=="chain")b=pts(26,44,(cx,cy,a)=>`<ellipse cx="${cx}" cy="${cy}" rx="6.5" ry="3.4" transform="rotate(${a*180/Math.PI+90*(Math.round(a*13/Math.PI)%2)} ${cx} ${cy})" fill="none" stroke="${x.a}" stroke-width="2.4"/>`);
if(x.t=="pearl")b=pts(20,44,(cx,cy)=>`<circle cx="${cx}" cy="${cy}" r="6.2" fill="${x.a}" stroke="#d9cfc6"/><circle cx="${cx-1.8}" cy="${cy-1.8}" r="1.8" fill="#fff"/>`);
if(x.t=="gem")b=`<circle cx="60" cy="60" r="44" fill="none" stroke="#b9c3cc" stroke-width="3"/>`+pts(18,44,(cx,cy,a)=>`<rect x="${cx-4.5}" y="${cy-4.5}" width="9" height="9" transform="rotate(45 ${cx} ${cy})" fill="${x.a}" stroke="#fff" stroke-width="1"/>`);
if(x.t=="heart")b=`<circle cx="60" cy="60" r="44" fill="none" stroke="#c9a24b" stroke-width="2.4" stroke-dasharray="1 4" stroke-linecap="round"/><circle cx="60" cy="60" r="44" fill="none" stroke="#c9a24b" stroke-width="1.6"/><path d="M60 112c-9-7-14-11-14-16a7 7 0 0 1 14-2 7 7 0 0 1 14 2c0 5-5 9-14 16z" transform="translate(0 -2)" fill="${x.a}"/>`;
if(x.t=="bangle")b=`<circle cx="60" cy="60" r="42" fill="none" stroke="${x.a}" stroke-width="9"/><circle cx="60" cy="60" r="42" fill="none" stroke="#fff" stroke-width="2" opacity=".5" stroke-dasharray="40 224" stroke-dashoffset="-10"/>`;
return `<svg width="130" height="150" viewBox="0 0 120 120">${b}</svg>`}
const art=x=>x.t=="img"?`<img src="${x.src?({IMG2,IMG3,IMG4,IMG5,IMG6,IMG7,IMG8,IMG9,IMG10,IMG11,IMG12,IMG13,IMG14,IMG15,IMG16,IMG17,IMG18,IMG19,IMG20,IMG21,IMG22,IMG23,IMG24,IMG25,IMG26,IMG27,IMG28,IMG29,IMG30,IMG31})[x.src]:IMG}" alt="${x.n}" style="width:100%;max-width:230px;border-radius:12px;display:block">`:x.t=="w"?watch(x):brace(x);
function draw(){
el("filters").innerHTML=cats.map(c=>`<button class="${c==cat?'on':''}" data-c="${c}">${c}</button>`).join("");
el("grid").innerHTML=P.filter(x=>cat=="الكل"||x.c==cat).map(x=>`<div class="card"><div class="img">${art(x)}</div><div class="info"><h3>${x.n}</h3><small>${x.l||(x.c=="ساعات"?"ساعة نسائية":x.c=="أطقم"?"طقم هدية":"سوار")}</small><div class="price">${x.p} ر.س</div><button data-add="${x.id}">أضيفي للسلة</button></div></div>`).join("");}
function cartUI(){
const ids=Object.keys(cart);let t=0,n=0;
el("items").innerHTML=ids.length?ids.map(i=>{const x=P.find(p=>p.id==i),q=cart[i];t+=x.p*q;n+=q;return `<div class="row"><span>${x.n}<br><small>${x.p} ر.س</small></span><span><button data-m="${i}">−</button> ${q} <button data-p="${i}">+</button></span></div>`}).join(""):"<p style='color:var(--muted)'>السلة فارغة</p>";
if(ids.length&&el("gift").checked)t+=15;
el("total").textContent=t+" ر.س";el("cnt").textContent=n;}
document.addEventListener("click",e=>{
const d=e.target.dataset;
if(d.c){cat=d.c;draw()}
if(d.add){cart[d.add]=(cart[d.add]||0)+1;cartUI();el("drawer").classList.add("open")}
if(d.p){cart[d.p]++;cartUI()}
if(d.m){if(--cart[d.m]<=0)delete cart[d.m];cartUI()}});
el("open").onclick=()=>el("drawer").classList.add("open");
el("close").onclick=()=>el("drawer").classList.remove("open");
el("gift").onchange=cartUI;
el("buy").onclick=()=>{const has=Object.keys(cart).length;el("msg").textContent=has?"شكراً لك! سنتواصل معك لتأكيد الطلب 🎁":"أضيفي منتجاً أولاً";if(has){cart={};cartUI()}};
draw();cartUI();
